export interface Page {
  title: string;
  slug: string;
  date?: string;
  tags: string[];
  body: string;
  html: string;
  excerpt: string;
  filePath: string;
}

export interface BuildResult {
  pages: number;
  outputDir: string;
  files: string[];
}

import fs from 'fs';
import path from 'path';
import MarkdownIt from 'markdown-it';
import matter from 'gray-matter';
import { Page } from './types';

const md = new MarkdownIt({ html: true, linkify: true, typographer: true });

export function slugify(input: string): string {
  const slug = input
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
  return slug || 'untitled';
}

function stripHtml(html: string): string {
  return html.replace(/<[^>]+>/g, ' ');
}

export function parseMarkdown(content: string, filePath: string): Page {
  const { data, content: body } = matter(content);

  const rawTitle = typeof data.title === 'string' ? data.title : '';
  const title = rawTitle.trim()
    ? rawTitle.trim()
    : path.basename(filePath, path.extname(filePath));

  const rawDate = typeof data.date === 'string' || data.date instanceof Date
    ? data.date.toString()
    : undefined;

  const rawTags = data.tags;
  const tags = Array.isArray(rawTags)
    ? rawTags.filter((t): t is string => typeof t === 'string')
    : [];

  const rawSlug = typeof data.slug === 'string' ? data.slug : '';
  const slug = slugify(rawSlug.trim() ? rawSlug : title);

  const html = md.render(body);
  const excerpt = stripHtml(html).trim().replace(/\s+/g, ' ').slice(0, 200);

  return {
    title,
    slug,
    date: rawDate,
    tags,
    body,
    html,
    excerpt,
    filePath,
  };
}

import fs from 'fs';
import path from 'path';
import { Page, BuildResult } from './types';
import { parseMarkdown } from './markdown';

export const DEFAULT_CONTENT_DIR = 'content';
export const DEFAULT_OUTPUT_DIR = 'dist';

function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

export function findMarkdownFiles(contentDir: string): string[] {
  const results: string[] = [];
  const walk = (dir: string): void => {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && /\.mdx?$/i.test(entry.name)) {
        results.push(full);
      }
    }
  };
  walk(contentDir);
  results.sort();
  return results;
}

export function readPages(contentDir: string): Page[] {
  const files = findMarkdownFiles(contentDir);
  return files.map((file) =>
    parseMarkdown(fs.readFileSync(file, 'utf8'), path.relative(contentDir, file))
  );
}

export function sortPages(pages: Page[]): Page[] {
  return [...pages].sort((a, b) => {
    const da = a.date ? new Date(a.date).getTime() : 0;
    const db = b.date ? new Date(b.date).getTime() : 0;
    if (da !== db) return db - da;
    return a.title.localeCompare(b.title);
  });
}

function renderTags(tags: string[]): string {
  return tags
    .map(
      (tag) =>
        `<a class="tag" href="?tag=${encodeURIComponent(tag)}">${escapeHtml(tag)}</a>`
    )
    .join('');
}

export function renderPage(page: Page): string {
  const dateHtml = page.date
    ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`
    : '';
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(page.title)}</title>
</head>
<body>
<nav><a href="./index.html">Home</a></nav>
<main>
<article>
<h1>${escapeHtml(page.title)}</h1>
${dateHtml}
<div class="tags">${renderTags(page.tags)}</div>
<div class="content">
${page.html}
</div>
</article>
</main>
</body>
</html>
`;
}

export function renderIndex(pages: Page[]): string {
  const items = pages
    .map((page) => {
      const dateHtml = page.date
        ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>`
        : '';
      const tagsHtml = page.tags
        .map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`)
        .join(' ');
      return `    <li class="page">
      <h2><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.title)}</a></h2>
      <p class="meta">${dateHtml} ${tagsHtml}</p>
      <p class="excerpt">${escapeHtml(page.excerpt)}</p>
    </li>`;
    })
    .join('\n');
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Home</title>
</head>
<body>
<main>
<h1>Pages</h1>
<ul class="pages">
${items}
</ul>
</main>
</body>
</html>
`;
}

export function buildSite(contentDir: string, outputDir: string): BuildResult {
  if (!fs.existsSync(contentDir)) {
    throw new Error(`content directory not found: ${contentDir}`);
  }
  const pages = sortPages(readPages(contentDir));
  fs.mkdirSync(outputDir, { recursive: true });

  const files: string[] = [];
  for (const page of pages) {
    const name = `${page.slug}.html`;
    fs.writeFileSync(path.join(outputDir, name), renderPage(page), 'utf8');
    files.push(name);
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages), 'utf8');
  files.push('index.html');

  return { pages: pages.length, outputDir, files };
}

import { buildSite, DEFAULT_CONTENT_DIR, DEFAULT_OUTPUT_DIR } from './site';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
}

export interface ParsedArgs {
  command: string;
  options: CliOptions;
}

export function printHelp(): void {
  console.log(
    [
      'Usage: ssg build [options]',
      '',
      'Generate a static site from Markdown files.',
      '',
      'Options:',
      '  --content <dir>   directory containing Markdown files (default: ./content)',
      '  --output <dir>    directory to write the generated site (default: ./dist)',
      '  -h, --help        show this help message',
    ].join('\n')
  );
}

export function parseArgs(argv: string[]): ParsedArgs {
  const args = [...argv];
  let command = 'build';
  if (args.length > 0 && !args[0].startsWith('-')) {
    command = args.shift() as string;
  }

  const options: CliOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content' || arg === '-c') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      options.contentDir = value;
    } else if (arg === '--output' || arg === '-o') {
      const value = args[++i];
      if (value === undefined) {
        throw new Error(`missing value for ${arg}`);
      }
      options.outputDir = value;
    } else if (arg === '--help' || arg === '-h') {
      printHelp();
      process.exit(0);
    } else {
      throw new Error(`unknown argument: ${arg}`);
    }
  }

  return { command, options };
}

export function run(argv: string[]): void {
  let parsed: ParsedArgs;
  try {
    parsed = parseArgs(argv);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }

  if (parsed.command !== 'build') {
    console.error(`unknown command: ${parsed.command}`);
    process.exit(1);
  }

  try {
    const result = buildSite(parsed.options.contentDir, parsed.options.outputDir);
    const pagesWord = result.pages === 1 ? 'page' : 'pages';
    console.log(`Built ${result.pages} ${pagesWord} into ${result.outputDir}`);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

import { parseMarkdown, slugify } from '../src/markdown';

describe('slugify', () => {
  it('lowercases and replaces spaces with dashes', () => {
    expect(slugify('My First Post')).toBe('my-first-post');
  });

  it('strips special characters', () => {
    expect(slugify('Hello, World!')).toBe('hello-world');
  });

  it('collapses repeated dashes', () => {
    expect(slugify('A  B---C')).toBe('a-b-c');
  });

  it('falls back to a default for empty input', () => {
    expect(slugify('!!!')).toBe('untitled');
  });
});

describe('parseMarkdown', () => {
  it('parses frontmatter title, date, and tags', () => {
    const page = parseMarkdown(
      [
        '---',
        'title: My First Post',
        'date: 2024-01-15',
        'tags: [typescript, cli]',
        '---',
        '# Hello',
        '',
        'Some **bold** text.',
      ].join('\n'),
      'my-first-post.md'
    );

    expect(page.title).toBe('My First Post');
    expect(page.date).toBe('2024-01-15');
    expect(page.tags).toEqual(['typescript', 'cli']);
    expect(page.html).toContain('<h1>Hello</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
  });

  it('uses the file name as the fallback title', () => {
    const page = parseMarkdown('# Just a heading', 'hello-world.md');
    expect(page.title).toBe('hello-world');
    expect(page.slug).toBe('hello-world');
  });

  it('handles content without frontmatter', () => {
    const page = parseMarkdown('Plain content', 'plain.md');
    expect(page.html).toContain('Plain content');
    expect(page.tags).toEqual([]);
    expect(page.date).toBeUndefined();
  });

  it('uses a frontmatter slug when provided', () => {
    const page = parseMarkdown(
      ['---', 'title: Weird Title', 'slug: custom-slug', '---', 'Body'].join('\n'),
      'weird.md'
    );
    expect(page.slug).toBe('custom-slug');
  });

  it('builds a text excerpt from the rendered html', () => {
    const page = parseMarkdown('# T\n\nSome <b>important</b> words.', 'x.md');
    expect(page.excerpt).toBe('T Some important words.');
  });
});

import fs from 'fs';
import os from 'os';
import path from 'path';
import {
  buildSite,
  findMarkdownFiles,
  readPages,
  sortPages,
  renderPage,
  renderIndex,
} from '../src/site';
import { Page } from '../src/types';

interface TempDir {
  dir: string;
  cleanup: () => void;
}

function makeTempDir(): TempDir {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
  return { dir, cleanup: () => fs.rmSync(dir, { recursive: true, force: true }) };
}

function writeContentFiles(contentDir: string): void {
  fs.mkdirSync(contentDir, { recursive: true });
  fs.writeFileSync(
    path.join(contentDir, 'one.md'),
    '---\ntitle: First Page\ndate: 2024-01-01\ntags: [a, b]\n---\n# First\nBody **here**.'
  );
  fs.writeFileSync(
    path.join(contentDir, 'two.md'),
    '---\ntitle: Second Page\ndate: 2024-02-01\ntags: [b]\n---\n# Second\nBody two.'
  );
}

describe('findMarkdownFiles', () => {
  it('finds markdown files recursively', () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    fs.mkdirSync(path.join(contentDir, 'sub'), { recursive: true });
    fs.writeFileSync(path.join(contentDir, 'a.md'), 'a');
    fs.writeFileSync(path.join(contentDir, 'sub', 'b.mdx'), 'b');
    fs.writeFileSync(path.join(contentDir, 'sub', 'c.txt'), 'c');

    const files = findMarkdownFiles(contentDir);
    expect(files.map((f) => path.basename(f)).sort()).toEqual(['a.md', 'b.mdx']);
    cleanup();
  });
});

describe('readPages', () => {
  it('reads and parses all markdown files in a directory', () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    writeContentFiles(contentDir);

    const pages = readPages(contentDir);
    expect(pages).toHaveLength(2);
    const titles = pages.map((p) => p.title).sort();
    expect(titles).toEqual(['First Page', 'Second Page']);
    cleanup();
  });
});

describe('sortPages', () => {
  it('sorts newest first by date', () => {
    const pages: Page[] = [
      { title: 'Old', slug: 'old', date: '2020-01-01', tags: [], body: '', html: '', excerpt: '', filePath: 'old.md' },
      { title: 'New', slug: 'new', date: '2024-01-01', tags: [], body: '', html: '', excerpt: '', filePath: 'new.md' },
    ];
    const sorted = sortPages(pages);
    expect(sorted[0].title).toBe('New');
    expect(sorted[1].title).toBe('Old');
  });

  it('sorts pages without dates last', () => {
    const pages: Page[] = [
      { title: 'Dated', slug: 'd', date: '2024-01-01', tags: [], body: '', html: '', excerpt: '', filePath: 'd.md' },
      { title: 'Undated', slug: 'u', tags: [], body: '', html: '', excerpt: '', filePath: 'u.md' },
    ];
    const sorted = sortPages(pages);
    expect(sorted[0].title).toBe('Dated');
    expect(sorted[1].title).toBe('Undated');
  });
});

describe('buildSite', () => {
  it('generates index.html and a page per markdown file', () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    writeContentFiles(contentDir);

    const result = buildSite(contentDir, outDir);
    expect(result.pages).toBe(2);
    expect(result.files).toContain('index.html');
    expect(result.files).toContain('first-page.html');
    expect(result.files).toContain('second-page.html');

    const index = fs.readFileSync(path.join(outDir, 'index.html'), 'utf8');
    expect(index).toContain('First Page');
    expect(index).toContain('first-page.html');
    expect(index).toContain('Second Page');

    const page = fs.readFileSync(path.join(outDir, 'first-page.html'), 'utf8');
    expect(page).toContain('<h1>First Page</h1>');
    expect(page).toContain('<strong>here</strong>');
    cleanup();
  });

  it('creates the output directory when it does not exist', () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'nested', 'dist');
    writeContentFiles(contentDir);

    buildSite(contentDir, outDir);
    expect(fs.existsSync(path.join(outDir, 'index.html'))).toBe(true);
    cleanup();
  });

  it('builds an empty index when there are no pages', () => {
    const { dir, cleanup } = makeTempDir();
    const contentDir = path.join(dir, 'content');
    const outDir = path.join(dir, 'dist');
    fs.mkdirSync(contentDir, { recursive: true });

    const result = buildSite(contentDir, outDir);
